import {getFinancingOffersList} from '../api_helpers';

export async function POST() {
  try {
    const session = await getServerSession(authOptions);

    if (!session) {
      return new Response('The current route requires authentication', {
        status: 403,
      });
    }

    const connected_account = session.user.stripeAccountId;

    const offer = (
      await getFinancingOffersList({
        connected_account: connected_account,
        limit: 1,
      })
    ).data
      .filter((o) => o.status === 'accepted')
      .at(0);

    if (offer === undefined) {
      throw Error(
        'Unable to find offer with status `accepted` for connected account: ' +
          connected_account
      );
    }

    await stripe.rawRequest(
      'POST',
      `/v1/capital/financing_offers/${offer!.id}/revoke_v2`,
      {}
    );

    return new Response(
      JSON.stringify({
        offer,
      }),
      {status: 200, headers: {'Content-Type': 'application/json'}}
    );
  } catch (error: any) {
    console.error(
      'An error occurred when calling the Stripe API to reject test financing offer',
      error
    );
    return new Response(error.message, {status: 500});
  }
}

import {Button} from '@/components/ui/button';
import {ExternalLinkIcon} from '@radix-ui/react-icons';
import {LoaderCircle} from 'lucide-react';
import React from 'react';
import {UseFormReturn} from 'react-hook-form';
import {OfferState} from './types';

export function CapitalAccountLinkButton({
  type,
}: {
  type: 'capital_financing_offer' | 'capital_financing_reporting';
}) {
  const [buttonLoading, setButtonLoading] = React.useState(false);
  const onClick = async () => {
    setButtonLoading(true);
    try {
      const url = new URL('/api/account_link', window.location.origin);
      url.searchParams.set('shouldRedirect', 'false');

      url.searchParams.set('type', type);

      const res = await fetch(url, {
        method: 'GET',
      });

      const accountLink = (await res.json()).url;
      window.open(accountLink, '_blank', 'noopener,noreferrer');
    } catch (e) {
      console.log('Error attempting to create capital account link: ', e);
    } finally {
      setButtonLoading(false);
    }
  };

  return (
    <Button onClick={onClick} className="border text-xs" variant="secondary">
      {!buttonLoading && (
        <div className="flex items-center gap-x-1">
          {type === 'capital_financing_offer' ? 'Offer ' : 'Reporting '}
          dashboard
          <ExternalLinkIcon className="h-3 w-3" />
        </div>
      )}
      {buttonLoading && (
        <LoaderCircle className="ml-2 animate-spin items-center" size={20} />
      )}
    </Button>
  );
}

